INSERT INTO shared_resources (id, test_id, resource_type, title, content_url, text_content, metadata, created_at) VALUES (34, 3, 'text', 'AI in university teaching and learning', NULL, 'In recent years, many universities have begun to integrate artificial intelligence (AI) into teaching and learning, and this trend is accelerating. Supporters of AI in education argue that it can transform the student experience in several important ways. First, AI tools can provide personalised feedback at scale. For example, writing assistants and learning platforms can quickly highlight common language errors, suggest improvements in structure, or point out gaps in understanding. This allows students to receive immediate, targeted support instead of waiting for a teacher''s comments, which can be particularly helpful in large classes where individual attention is limited.
