INSERT INTO question_groups (id, test_id, test_part_id, dimension_id, shared_resource_id, group_code, canonical_number, legacy_qid, variant_count, sort_order, response_type) VALUES (208, 3, 5, 24, NULL, '008', 8, 'S8', 1, 8, 'speaking');
INSERT INTO questions (id, question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (208, 208, '03-01-08-008-01', '01', 'You and a friend have to organise a community clean-up day in your neighbourhood to encourage more environmentally friendly behaviour. You now have two minutes to prepare a short speech. After that, you will have two minutes to deliver your speech directly to the people in your community, trying to persuade them to take part in this event. In your speech, explain why the clean-up day is important, how it will benefit the neighbourhood, and what will happen during the event. You can also mention how people can join, and use strong, clear messages to encourage them to participate.
INSERT INTO question_groups (id, test_id, test_part_id, dimension_id, shared_resource_id, group_code, canonical_number, legacy_qid, variant_count, sort_order, response_type) VALUES (209, 3, 6, 25, 34, '009', 9, 'W1', 1, 9, 'writing');
INSERT INTO questions (id, question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (209, 209, '03-02-01-009-01', '01', 'Read the text. In about 100-150 words, summarise the writer''s main ideas and give your reaction.', '', '', '', '', 'N/A', '{"responseType":"writing","wordMin":100,"wordMax":150,"guidelines":"Do not copy sentences from the text. First, briefly summarise the main points in your own words. Then give your reaction, supported by reasons and, if possible, examples. Use a clear, logical structure and appropriate formal or semi-formal register."}', 1753027200000);
INSERT INTO question_groups (id, test_id, test_part_id, dimension_id, shared_resource_id, group_code, canonical_number, legacy_qid, variant_count, sort_order, response_type) VALUES (210, 3, 6, 26, NULL, '010', 10, 'W2', 1, 10, 'writing');
INSERT INTO questions (id, question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (210, 210, '03-02-02-010-01', '01', 'Many universities are increasing the use of online learning. Do you think this is a positive or negative development for students'' education? Write a short essay discussing your opinion and giving reasons and examples to support your view.', '', '', '', '', 'N/A', '{"responseType":"writing","wordMin":200,"wordMax":300,"guidelines":"Write about 200–300 words. Use a clear structure (introduction, main body, conclusion). State your position and support it with reasons and examples. Aim for formal, academic style English."}', 1753027200000);
